class Solution {
public:
    int binarySearchableNumbers(vector<int>& nums) {
        int n = nums.size();
        vector<int> suffix(n + 1, INT_MAX);
        for (int i = n - 1; i >= 0; --i) {
            suffix[i] = min(suffix[i + 1], nums[i]);
        }
        int prefix = INT_MIN, answer = 0;
        for (int i = 0; i < n; ++i) {
            if (prefix < nums[i] && nums[i] < suffix[i + 1]) {
                ++answer;
            }
            prefix = max(prefix, nums[i]);
        }
        return answer;
    }
};
